package vn.edu.huy;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.sql.*;
import org.jsoup.Jsoup;import org.jsoup.nodes.Document;import org.apache.catalina.startup.Tomcat;
import vn.edu.huy.util.*;import vn.edu.huy.dao.impl.*;import vn.edu.huy.model.*;
@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
public class IntegrationTest_24162049 {
 static Tomcat tomcat;static HttpClient guest,admin,user;static final String BASE="http://127.0.0.1:18080/video-24162049";
 static HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).followRedirects(HttpClient.Redirect.NEVER).build();}
 static HttpResponse<String> get(HttpClient c,String path)throws Exception{return c.send(HttpRequest.newBuilder(URI.create(BASE+path)).GET().build(),HttpResponse.BodyHandlers.ofString());}
 static String token(HttpResponse<String> r){var e=Jsoup.parse(r.body()).selectFirst("input[name=csrf]");assertNotNull(e,"CSRF form missing: "+r.body().substring(0,Math.min(250,r.body().length())));return e.attr("value");}
 static HttpResponse<String> post(HttpClient c,String path,Map<String,String> fields)throws Exception{String body=fields.entrySet().stream().map(e->URLEncoder.encode(e.getKey(),StandardCharsets.UTF_8)+"="+URLEncoder.encode(e.getValue(),StandardCharsets.UTF_8)).collect(java.util.stream.Collectors.joining("&"));return c.send(HttpRequest.newBuilder(URI.create(BASE+path)).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
 static HttpResponse<String> login(HttpClient c,String name)throws Exception {String csrf=token(get(c,"/login"));return post(c,"/login",Map.of("csrf",csrf,"username",name,"password","Demo@123"));}
 static int scalar(String sql)throws Exception{try(Connection c=ConnectionUtil_24162049.getConnection();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){r.next();return r.getInt(1);}}
 @BeforeAll static void start()throws Exception{tomcat=LocalRuntime_24162049.start(18080,true);guest=client();admin=client();user=client();}
 @AfterAll static void stop()throws Exception{tomcat.stop();tomcat.destroy();LocalRuntime_24162049.mail.stop();}
 @Test @Order(1) void seedAndPublicPages()throws Exception{assertEquals(14,scalar("SELECT COUNT(*) FROM Users"));assertEquals(2,scalar("SELECT COUNT(*) FROM Users WHERE Admin=1"));assertEquals(16,scalar("SELECT COUNT(*) FROM Videos"));for(String route:List.of("/home","/products","/register","/login")){var r=get(guest,route);assertEquals(200,r.statusCode(),route);assertTrue(r.body().contains("Nguyễn Quốc Gia Huy"));assertTrue(r.body().contains("24162049"));assertEquals(1,Jsoup.parse(r.body()).select("footer").size());}assertEquals(404,get(guest,"/missing-page").statusCode());}
 @Test @Order(2) void authAndRoleGuards()throws Exception{assertEquals(302,get(guest,"/admin").statusCode());assertTrue(login(admin,"admin").headers().firstValue("location").orElse("").endsWith("/admin"));assertTrue(login(user,"user01").headers().firstValue("location").orElse("").endsWith("/home"));assertEquals(403,get(user,"/admin").statusCode());assertEquals(403,get(user,"/admin/users/create").statusCode());var locked=client();assertTrue(post(locked,"/login",Map.of("csrf",token(get(locked,"/login")),"username","user12","password","Demo@123")).body().contains("chưa được kích hoạt"));}
 @Test @Order(3) void userPaginationSearchAndBoundaries()throws Exception{var page1=Jsoup.parse(get(admin,"/admin/users").body());assertEquals(6,page1.select("tbody tr").size());assertEquals(2,Jsoup.parse(get(admin,"/admin/users?page=999").body()).select("tbody tr").size());assertTrue(get(admin,"/admin/users?page=-1").body().contains("Trang 1 / 3"));String search=get(admin,"/admin/users?q=user&page=2").body();assertEquals(6,Jsoup.parse(search).select("tbody tr").size());assertTrue(search.contains("q=user"));assertTrue(get(admin,"/admin/users?q=%25").body().contains("Không tìm thấy"));assertTrue(get(admin,"/admin/users?q=%27%20OR%201%3D1--").body().contains("Không tìm thấy"));}
 @Test @Order(4) void categoryPagingAndAggregates()throws Exception{String page=get(guest,"/products?categoryId=1").body();assertEquals(3,Jsoup.parse(page).select(".video-card").size());assertTrue(page.contains("Du lịch (4)"));assertTrue(page.contains("3 Like"));assertTrue(page.contains("2 Share"));assertTrue(page.contains("categoryId=1"));assertEquals(1,Jsoup.parse(get(guest,"/products?categoryId=1&page=99").body()).select(".video-card").size());assertTrue(get(guest,"/products?categoryId=1&page=-5").body().contains("Trang 1 / 2"));assertEquals(404,get(guest,"/products?categoryId=999").statusCode());}
 @Test @Order(5) void viewCountingAnd404()throws Exception{int before=scalar("SELECT Views FROM Videos WHERE VideoId='VID001'");assertEquals(200,get(guest,"/video/detail?id=VID001").statusCode());assertEquals(before+1,scalar("SELECT Views FROM Videos WHERE VideoId='VID001'"));assertEquals(404,get(guest,"/video/detail?id=invalid").statusCode());assertEquals(404,get(guest,"/video/detail?id=%27%20OR%201%3D1--").statusCode());}
 @Test @Order(6) void mutationsRequirePostAndCsrf()throws Exception{assertEquals(405,get(admin,"/admin/users/delete?username=user06").statusCode());assertEquals(405,get(user,"/video/like?id=VID001").statusCode());assertEquals(405,get(user,"/logout").statusCode());assertEquals(403,post(admin,"/admin/users/delete",Map.of("username","user06")).statusCode());assertNotNull(new UserDaoImpl_24162049().find("user06"));}
 @Test @Order(7) void crudPreservesPasswordAndEscapesHtml()throws Exception{String csrf=token(get(admin,"/admin/users/create"));Map<String,String> form=new HashMap<>(Map.of("csrf",csrf,"username","qauser","fullname","<b>Kiểm thử</b>","email","qauser@example.com","phone","0901234567","password","Demo@123","active","on"));assertEquals(302,post(admin,"/admin/users/create",form).statusCode());UserDaoImpl_24162049 dao=new UserDaoImpl_24162049();String hash=dao.find("qauser").getPassword();assertTrue(hash.startsWith("$2a$"));String detail=get(admin,"/admin/users/detail?username=qauser").body();assertTrue(detail.contains("&lt;b&gt;Kiểm thử&lt;/b&gt;"));assertFalse(detail.contains(hash));form.put("password","");form.put("fullname","Đã cập nhật");assertEquals(302,post(admin,"/admin/users/edit",form).statusCode());assertEquals(hash,dao.find("qauser").getPassword());assertEquals("Đã cập nhật",dao.find("qauser").getFullname());assertEquals(302,post(admin,"/admin/users/delete",Map.of("csrf",csrf,"username","qauser")).statusCode());assertNull(dao.find("qauser"));}
 @Test @Order(8) void selfAndForeignKeyDeleteAreBlocked()throws Exception{String csrf=token(get(admin,"/admin/users"));post(admin,"/admin/users/delete",Map.of("csrf",csrf,"username","admin"));assertTrue(get(admin,"/admin/users").body().contains("không thể tự xóa"));post(admin,"/admin/users/delete",Map.of("csrf",csrf,"username","user01"));assertTrue(get(admin,"/admin/users").body().contains("đã có lượt thích hoặc chia sẻ"));}
 @Test @Order(9) void likeIsIdempotentAndReversible()throws Exception{String csrf=token(get(user,"/video/detail?id=VID001"));int before=scalar("SELECT COUNT(*) FROM Favorites WHERE VideoId='VID001'");post(user,"/video/like",Map.of("csrf",csrf,"id","VID001","liked","false"));assertEquals(before-1,scalar("SELECT COUNT(*) FROM Favorites WHERE VideoId='VID001'"));post(user,"/video/like",Map.of("csrf",csrf,"id","VID001","liked","true"));post(user,"/video/like",Map.of("csrf",csrf,"id","VID001","liked","true"));assertEquals(before,scalar("SELECT COUNT(*) FROM Favorites WHERE VideoId='VID001'"));}
 @Test @Order(10) void shareDeliversEmailAndPersists()throws Exception{String csrf=token(get(user,"/video/detail?id=VID001"));int before=scalar("SELECT COUNT(*) FROM Shares WHERE VideoId='VID001'");int mails=LocalRuntime_24162049.mail.getReceivedMessages().length;assertEquals(302,post(user,"/video/share",Map.of("csrf",csrf,"id","VID001","email","receiver@example.com")).statusCode());assertEquals(before+1,scalar("SELECT COUNT(*) FROM Shares WHERE VideoId='VID001'"));assertTrue(LocalRuntime_24162049.mail.waitForIncomingEmail(2000,mails+1));String text=LocalRuntime_24162049.mail.getReceivedMessages()[mails].getContent().toString();assertTrue(text.contains("/video/detail?id=VID001"));assertTrue(get(user,"/video/detail?id=VID001").body().contains("Đã gửi email"));}
 @Test @Order(11) void registrationOtpAndActivation()throws Exception{HttpClient c=client();String csrf=token(get(c,"/register"));int mails=LocalRuntime_24162049.mail.getReceivedMessages().length;var fields=new HashMap<>(Map.of("csrf",csrf,"username","otpuser","fullname","Người dùng OTP","email","otpuser@example.com","phone","0901234567","password","Demo@123","confirm","Demo@123"));assertEquals(302,post(c,"/register",fields).statusCode());assertNull(new UserDaoImpl_24162049().find("otpuser"));assertTrue(LocalRuntime_24162049.mail.waitForIncomingEmail(2000,mails+1));String text=LocalRuntime_24162049.mail.getReceivedMessages()[mails].getContent().toString();var matcher=java.util.regex.Pattern.compile("[0-9]{6}").matcher(text);assertTrue(matcher.find());String otp=matcher.group();assertEquals(200,get(c,"/verify-otp").statusCode());post(c,"/resend-otp",Map.of("csrf",csrf));assertEquals(mails+1,LocalRuntime_24162049.mail.getReceivedMessages().length);assertTrue(get(c,"/verify-otp").body().contains("60 giây"));String wrong=otp.equals("000000")?"111111":"000000";assertTrue(post(c,"/verify-otp",Map.of("csrf",csrf,"otp",wrong)).body().contains("không chính xác"));assertEquals(302,post(c,"/verify-otp",Map.of("csrf",csrf,"otp",otp)).statusCode());assertTrue(new UserDaoImpl_24162049().find("otpuser").isActive());assertFalse(new UserDaoImpl_24162049().find("otpuser").isAdmin());assertEquals(302,login(c,"otpuser").statusCode());}
 @Test @Order(12) void serverValidationAndUniqueConstraints()throws Exception{HttpClient c=client();String csrf=token(get(c,"/register"));var f=new HashMap<>(Map.of("csrf",csrf,"username","admin","fullname","Thử nghiệm","email","unique@example.com","phone","0901234567","password","Demo@123","confirm","different"));assertTrue(post(c,"/register",f).body().contains("chưa khớp"));f.put("confirm","Demo@123");assertTrue(post(c,"/register",f).body().contains("đã tồn tại"));f.put("username","validuser");f.put("email","not-email");assertTrue(post(c,"/register",f).body().contains("email không hợp lệ"));}
 @Test @Order(13) void sequenceIsUniqueUnderConcurrency()throws Exception{var pool=java.util.concurrent.Executors.newFixedThreadPool(4);try{List<java.util.concurrent.Future<String>> futures=new ArrayList<>();for(int i=0;i<12;i++)futures.add(pool.submit(()->{Video_24162049 v=new Video_24162049();v.setTitle("Kiểm thử sequence");v.setPoster("/assets/posters/1.svg");v.setDescription("Dữ liệu thử");v.setActive(false);v.setCategoryId(1);return new VideoDaoImpl_24162049().create(v);}));Set<String> ids=new HashSet<>();for(var f:futures)ids.add(f.get());assertEquals(12,ids.size());assertFalse(ids.contains("VID001"));}finally{pool.shutdownNow();}}
 @Test @Order(14) void emptyCategoryAndInactiveVideo()throws Exception{try(Connection c=ConnectionUtil_24162049.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO Category(CategoryName,CategoryCode,Status) VALUES (?,?,?)")){p.setString(1,"Chủ đề trống");p.setString(2,"EMPTY");p.setBoolean(3,true);p.executeUpdate();}assertTrue(get(guest,"/products?categoryId=5").body().contains("Chưa có video"));assertEquals(404,get(guest,"/video/detail?id=VID017").statusCode());}
 @Test @Order(15) void cartHonorsQuantityAndStockLimits()throws Exception{HttpClient c=client();String csrf=token(get(c,"/products"));assertEquals(302,post(c,"/cart/add",Map.of("csrf",csrf,"id","VID001","quantity","2")).statusCode());String cart=get(c,"/cart").body();assertTrue(cart.contains("value=\"2\""));post(c,"/cart/update",Map.of("csrf",csrf,"id","VID001","quantity","99"));assertTrue(get(c,"/cart").body().contains("Số lượng phải từ 1 đến"));post(c,"/cart/remove",Map.of("csrf",csrf,"id","VID001"));assertTrue(get(c,"/cart").body().contains("Giỏ hàng đang trống"));}
 @Test @Order(16) void codCheckoutAndStatusHistory()throws Exception{String csrf=token(get(user,"/products"));int stock=scalar("SELECT Stock FROM Videos WHERE VideoId='VID002'");post(user,"/cart/add",Map.of("csrf",csrf,"id","VID002","quantity","2"));assertEquals(200,get(user,"/checkout").statusCode());var placed=post(user,"/checkout",Map.of("csrf",csrf,"recipientName","Lê Hoàng Nam","phone","0901234502","address","12 Nguyễn Huệ, Quận 1, TP.HCM","note","Giao giờ hành chính"));assertEquals(302,placed.statusCode());assertEquals(stock-2,scalar("SELECT Stock FROM Videos WHERE VideoId='VID002'"));assertEquals(1,scalar("SELECT COUNT(*) FROM Orders WHERE Username='user01' AND PaymentMethod='COD' AND Status='NEW'"));assertTrue(get(user,"/orders?status=NEW").body().contains("Đơn hàng mới"));try(Connection c=ConnectionUtil_24162049.getConnection();PreparedStatement p=c.prepareStatement("UPDATE Orders SET Status='DELIVERED' WHERE Username='user01'")){p.executeUpdate();}assertTrue(get(user,"/orders?status=DELIVERED").body().contains("Đã giao"));assertTrue(get(user,"/cart").body().contains("Giỏ hàng đang trống"));}
 @Test @Order(17) void logoutInvalidatesSession()throws Exception{String csrf=token(get(user,"/home"));assertEquals(302,post(user,"/logout",Map.of("csrf",csrf)).statusCode());assertTrue(get(user,"/home").body().contains("Tạo tài khoản"));assertEquals(302,get(user,"/video/like").statusCode());assertEquals(302,get(user,"/orders").statusCode());}
}
